//! Performance baseline for the JSONL store and the SQLite index (plan Phase 7).
//!
//! These are **measurements, not assertions**: every test is `#[ignore]`d, so the default
//! `cargo test` is unchanged. Run them explicitly and read the numbers from stdout:
//!
//! ```sh
//! cargo test --release -p radian-session --test perf_session -- --ignored --nocapture
//! ```
//!
//! Inputs are generated by [`write_session`], which writes valid v1 JSONL directly (the
//! same envelope and `MessageAppended` shape the reader validates). It deliberately does not
//! go through the writer's per-record fsync, because `Session::open` measures the **read**
//! path and a 100k-event file would otherwise cost 100k fsyncs to create.

mod common;

use std::fs::File;
use std::io::{BufWriter, Write};
use std::path::Path;
use std::time::{Duration, Instant};

use common::{TempDir, created};
use radian_core::{JournalRecord, Message, TranscriptJournal};
use radian_session::{Index, Session, SessionJournal};
use serde_json::json;

/// A fixed, format-valid timestamp: the reader checks the shape, not the value.
const TS: &str = "2026-10-12T00:00:00.000000Z";

/// Writes `n` messages into `path` as a valid v1 session file (header + `MessageAppended`).
fn write_session(path: &Path, session_id: &str, n: usize) {
    let mut out = BufWriter::new(File::create(path).unwrap());
    let header = json!({
        "schema_version": 1, "session_id": session_id, "seq": 0, "ts": TS,
        "event": "SessionCreated", "critical": true,
        "data": {"workspace": "/work/example", "config_snapshot": {}}
    });
    writeln!(out, "{header}").unwrap();
    for i in 0..n {
        let message = if i % 2 == 0 {
            Message::user(format!("user message {i} with some words on it"))
        } else {
            Message::assistant(format!("assistant reply {i} with some words on it"))
        };
        let line = json!({
            "schema_version": 1, "session_id": session_id, "seq": i + 1, "ts": TS,
            "event": "MessageAppended", "critical": true,
            "data": {"index": i, "message": serde_json::to_value(&message).unwrap()}
        });
        writeln!(out, "{line}").unwrap();
    }
    out.flush().unwrap();
}

fn median_p95(mut samples: Vec<Duration>) -> (Duration, Duration, Duration) {
    samples.sort();
    let n = samples.len();
    let median = samples[n / 2];
    let p95 = samples[(n * 95 / 100).min(n - 1)];
    let max = samples[n - 1];
    (median, p95, max)
}

fn ms(d: Duration) -> f64 {
    d.as_secs_f64() * 1000.0
}

/// One `append` (write + flush + fsync). The per-record cost ADR 0006 §10 measured; the
/// distribution matters because the core awaits each one.
#[tokio::test]
#[ignore = "measurement, not an assertion; run with --ignored --nocapture"]
async fn perf_append_latency() {
    let dir = TempDir::new("perf-append");
    let path = dir.file("s.jsonl");
    let journal = SessionJournal::create(&path, "perf", created()).unwrap();
    for i in 0..10 {
        journal
            .append(JournalRecord::Message {
                index: i,
                message: Message::assistant(format!("warm {i}")),
            })
            .await
            .unwrap();
    }
    let n = 200;
    let mut samples = Vec::with_capacity(n);
    for i in 0..n {
        let start = Instant::now();
        journal
            .append(JournalRecord::Message {
                index: 10 + i,
                message: Message::assistant(format!("line {i}")),
            })
            .await
            .unwrap();
        samples.push(start.elapsed());
    }
    let (median, p95, max) = median_p95(samples);
    println!(
        "append+flush+fsync: median {:.3} ms  p95 {:.3} ms  max {:.3} ms  (n={n})",
        ms(median),
        ms(p95),
        ms(max)
    );
}

/// `Session::open` over 1k / 10k / 100k events. Reports the whole open (file read, parse,
/// validation) and re-reads the same file three times to show a warm median.
#[test]
#[ignore = "measurement, not an assertion; run with --ignored --nocapture"]
fn perf_session_open() {
    let dir = TempDir::new("perf-open");
    for n in [1_000usize, 10_000, 100_000] {
        let path = dir.file(&format!("open-{n}.jsonl"));
        write_session(&path, &format!("open-{n}"), n);
        // Sanity: the generated file must actually parse, or the timing means nothing.
        let events = Session::open(&path).unwrap().events().len();
        assert_eq!(events, n + 1, "generated file must parse (header + n)");

        let mut samples = Vec::new();
        for _ in 0..5 {
            let start = Instant::now();
            let session = Session::open(&path).unwrap();
            samples.push(start.elapsed());
            std::hint::black_box(session.events().len());
        }
        let (median, p95, max) = median_p95(samples);
        println!(
            "Session::open {n:>6} events: median {:.3} ms  p95 {:.3} ms  max {:.3} ms",
            ms(median),
            ms(p95),
            ms(max)
        );
    }
}

/// SQLite index rebuild from zero. `sessions` files of `events` messages each; the index
/// file starts empty each time.
#[test]
#[ignore = "measurement, not an assertion; run with --ignored --nocapture"]
fn perf_index_rebuild() {
    let dir = TempDir::new("perf-index");
    for (files, events) in [(10usize, 1_000usize), (10, 10_000)] {
        let mut paths = Vec::new();
        for f in 0..files {
            let path = dir.file(&format!("idx-{events}-{f}.jsonl"));
            write_session(&path, &format!("idx-{events}-{f}"), events);
            paths.push(path);
        }
        let db = dir.file(&format!("idx-{events}.sqlite"));
        let mut index = Index::open(&db).unwrap();
        let start = Instant::now();
        let warnings = index.rebuild(&paths).unwrap();
        let elapsed = start.elapsed();
        assert!(warnings.is_empty(), "{warnings:?}");
        let total = files * events;
        println!(
            "Index::rebuild {total:>7} events in {files} files: {:.1} ms ({:.1} us/event)",
            ms(elapsed),
            elapsed.as_secs_f64() * 1e6 / total as f64
        );
    }
}
